WITH latest AS (SELECT * FROM order_items QUALIFY RANK() OVER (PARTITION BY product_id ORDER BY quantity NULLS FIRST) = 1), with_dims AS (SELECT src.*, b.category FROM latest src LEFT JOIN products b ON src.product_id = b.id), latest_order_items AS (SELECT id, unit_price FROM with_dims QUALIFY ROW_NUMBER() OVER (PARTITION BY category ORDER BY quantity DESC, id) = 1), cleaned AS (SELECT *, ROUND(unit_price, 2) AS unit_price_rounded, CASE WHEN unit_price >= 340 THEN 'High' WHEN unit_price >= 150 THEN 'Medium' ELSE 'Low' END AS unit_price_level FROM latest_order_items WHERE unit_price < 250), cleaned_order_items AS (SELECT *, ROUND(unit_price_rounded / unit_price, 2) AS unit_price_rounded_per_unit_price, unit_price + unit_price_rounded AS unit_price_plus_unit_price_rounded FROM cleaned WHERE unit_price BETWEEN 110 AND 190) SELECT id, unit_price, unit_price_rounded, unit_price_rounded_per_unit_price, SUM(unit_price_rounded) OVER w_ordered AS last7_sum_unit_price_rounded, AVG(unit_price_rounded) OVER w_ordered AS last7_avg_unit_price_rounded, COUNT(unit_price_rounded) OVER w_ordered AS last7_count_unit_price_rounded, MIN(unit_price_rounded) OVER w_ordered AS last7_min_unit_price_rounded, SUM(unit_price_rounded) OVER (ORDER BY unit_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_unit_price_rounded FROM cleaned_order_items WINDOW w_ordered AS (ORDER BY unit_price_plus_unit_price_rounded, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW);
